from fastapi import APIRouter, Request
from fastapi.responses import Response

router = APIRouter()

ACL_LOGO_B64 = ""


@router.get(".js")
async def serve_widget_js(request: Request):
    base_url = str(request.base_url).rstrip("/")
    js = f"""
(function() {{
  var script = document.currentScript;
  var tenant   = script.getAttribute('data-tenant')   || 'general';
  var theme    = script.getAttribute('data-theme')    || 'light';
  var position = script.getAttribute('data-position') || 'bottom-right';
  var apiBase  = '{base_url}';

  var style = document.createElement('style');
  style.textContent = `
    #intellirag-launcher {{
      position: fixed; right: 24px; bottom: 24px;
      width: 54px; height: 54px; border-radius: 50%;
      background: #060B4E; border: none; cursor: pointer;
      box-shadow: 0 4px 16px rgba(6,11,78,0.35);
      z-index: 9998; display: flex; align-items: center; justify-content: center;
      transition: transform 0.2s, box-shadow 0.2s;
    }}
    #intellirag-launcher:hover {{ transform: scale(1.07); box-shadow: 0 6px 20px rgba(6,11,78,0.45); }}
    #intellirag-launcher-bar {{
      position: fixed; right: 24px; bottom: 78px;
      width: 54px; height: 3px; border-radius: 2px; z-index: 9998; display: flex;
    }}
    #intellirag-iframe-wrap {{
      position: fixed; right: 24px; bottom: 96px;
      width: 400px; height: 580px; border-radius: 16px;
      overflow: hidden; box-shadow: 0 20px 60px rgba(6,11,78,0.22);
      z-index: 9999; display: none;
      border: 1px solid rgba(6,11,78,0.12);
    }}
    #intellirag-iframe-wrap.open {{ display: block; animation: irSlideUp 0.25s ease; }}
    @keyframes irSlideUp {{
      from {{ opacity:0; transform: translateY(16px); }}
      to   {{ opacity:1; transform: translateY(0); }}
    }}
    #intellirag-iframe {{ width:100%; height:100%; border:none; }}
  `;
  document.head.appendChild(style);

  // Orange+blue bar above button
  var bar = document.createElement('div');
  bar.id = 'intellirag-launcher-bar';
  bar.innerHTML = '<div style="width:65%;background:#FA9600;border-radius:2px 0 0 2px"></div><div style="width:35%;background:#0096D5;border-radius:0 2px 2px 0"></div>';
  document.body.appendChild(bar);

  // Launcher button
  var btn = document.createElement('button');
  btn.id = 'intellirag-launcher';
  btn.title = 'ACL IntelliRAG Assistant';
  btn.innerHTML = `<svg width="24" height="24" fill="none" viewBox="0 0 24 24">
    <path d="M8 10h8M8 14h5" stroke="#FA9600" stroke-width="1.8" stroke-linecap="round"/>
    <path d="M12 3C7.03 3 3 6.69 3 11.2c0 2.37 1.1 4.5 2.87 6.01L5 21l3.67-1.57C9.72 19.8 10.84 20 12 20c4.97 0 9-3.69 9-8.2C21 6.69 16.97 3 12 3z"
      stroke="#0096D5" stroke-width="1.8" stroke-linejoin="round"/>
  </svg>`;
  document.body.appendChild(btn);

  // iFrame container
  var wrap = document.createElement('div');
  wrap.id = 'intellirag-iframe-wrap';
  var iframe = document.createElement('iframe');
  iframe.id = 'intellirag-iframe';
  iframe.src = apiBase + '/widget/chat?tenant=' + tenant + '&theme=' + theme;
  wrap.appendChild(iframe);
  document.body.appendChild(wrap);

  var open = false;
  btn.addEventListener('click', function() {{
    open = !open;
    wrap.classList.toggle('open', open);
    btn.innerHTML = open
      ? `<svg width="20" height="20" fill="none" viewBox="0 0 24 24"><path d="M18 6L6 18M6 6l12 12" stroke="#FA9600" stroke-width="2" stroke-linecap="round"/></svg>`
      : `<svg width="24" height="24" fill="none" viewBox="0 0 24 24"><path d="M8 10h8M8 14h5" stroke="#FA9600" stroke-width="1.8" stroke-linecap="round"/><path d="M12 3C7.03 3 3 6.69 3 11.2c0 2.37 1.1 4.5 2.87 6.01L5 21l3.67-1.57C9.72 19.8 10.84 20 12 20c4.97 0 9-3.69 9-8.2C21 6.69 16.97 3 12 3z" stroke="#0096D5" stroke-width="1.8" stroke-linejoin="round"/></svg>`;
  }});
}})();
"""
    return Response(content=js, media_type="application/javascript")


@router.get("/chat")
async def widget_chat_page(tenant: str = "general", theme: str = "light"):
    logo_data_uri = f"data:image/png;base64,{ACL_LOGO_B64}"
    html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1.0"/>
<title>ACL IntelliRAG</title>
<style>
  *,*::before,*::after{{box-sizing:border-box;margin:0;padding:0}}
  body{{font-family:-apple-system,BlinkMacSystemFont,'Inter','Segoe UI',sans-serif;
    background:#fff;height:100vh;display:flex;flex-direction:column;font-size:14px;}}

  .header{{background:#060B4E;flex-shrink:0}}
  .header-inner{{display:flex;align-items:center;gap:10px;padding:10px 14px}}
  .header-logo{{height:26px;width:auto}}
  .header-divider{{width:1px;height:20px;background:rgba(255,255,255,.2)}}
  .header-title{{font-weight:600;font-size:14px;color:#fff;flex:1}}
  .header-tenant{{font-size:11px;color:rgba(255,255,255,.65);background:rgba(255,255,255,.1);padding:2px 9px;border-radius:10px}}
  .header-dot{{width:7px;height:7px;border-radius:50%;background:#34D399}}
  .acl-bar{{display:flex;height:2px}}
  .acl-bar-o{{width:65%;background:#FA9600}}
  .acl-bar-b{{width:35%;background:#0096D5}}

  .messages{{flex:1;overflow-y:auto;padding:14px;display:flex;flex-direction:column;gap:11px}}
  .msg{{display:flex;gap:8px;align-items:flex-end;max-width:92%}}
  .msg.user{{flex-direction:row-reverse;align-self:flex-end}}
  .msg.bot{{align-self:flex-start}}
  .avatar{{width:27px;height:27px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;color:#fff;flex-shrink:0}}
  .avatar.bot{{background:#060B4E}}
  .avatar.user{{background:#FA9600}}
  .bubble{{padding:9px 13px;border-radius:13px;line-height:1.6;font-size:13px}}
  .bubble.user{{background:#060B4E;color:#fff;border-bottom-right-radius:3px}}
  .bubble.bot{{background:#F5F7FA;color:#060B4E;border-bottom-left-radius:3px}}
  .sources{{display:flex;flex-wrap:wrap;gap:4px;margin-top:5px}}
  .src-chip{{font-size:10px;padding:2px 8px;border-radius:7px;background:#FFF4E0;color:#854F0B;border:1px solid #FED7AA}}
  .conf{{display:flex;align-items:center;gap:5px;margin-top:5px;font-size:10px;color:#94A3B8}}
  .conf-track{{width:52px;height:3px;background:#E2E8F2;border-radius:2px;overflow:hidden}}
  .conf-fill{{height:100%;background:#10B981;border-radius:2px}}
  .typing{{display:flex;gap:4px;padding:10px 13px;background:#F5F7FA;border-radius:13px;border-bottom-left-radius:3px}}
  .typing span{{width:6px;height:6px;border-radius:50%;background:#94A3B8;display:inline-block;animation:bounce 1.2s infinite}}
  .typing span:nth-child(2){{animation-delay:.15s}}
  .typing span:nth-child(3){{animation-delay:.3s}}
  @keyframes bounce{{0%,80%,100%{{transform:translateY(0)}}40%{{transform:translateY(-4px)}}}}

  .input-area{{padding:10px 12px;border-top:1px solid #E2E8F2;background:#fff;flex-shrink:0}}
  .input-row{{display:flex;gap:8px;align-items:flex-end}}
  textarea{{flex:1;resize:none;border:1px solid #E2E8F2;border-radius:10px;padding:9px 12px;font-size:13px;color:#060B4E;background:#F5F7FA;font-family:inherit;line-height:1.5;max-height:100px;outline:none}}
  textarea:focus{{border-color:#FA9600}}
  button.send{{width:36px;height:36px;border-radius:50%;border:none;cursor:pointer;display:flex;align-items:center;justify-content:center;flex-shrink:0;transition:background .15s}}
  button.send:disabled{{background:#CBD5E1;cursor:not-allowed}}
  button.send:not(:disabled){{background:#FA9600}}
  .powered{{text-align:center;font-size:10px;color:#94A3B8;padding:5px 0 0}}
</style>
</head>
<body>

<div class="header">
  <div class="header-inner">
    <img class="header-logo" src="{logo_data_uri}" alt="ACL Digital"/>
    <div class="header-divider"></div>
    <span class="header-title">IntelliRAG</span>
    <div class="header-dot"></div>
    <span class="header-tenant">{tenant}</span>
  </div>
  <div class="acl-bar"><div class="acl-bar-o"></div><div class="acl-bar-b"></div></div>
</div>

<div class="messages" id="messages">
  <div class="msg bot">
    <div class="avatar bot">IR</div>
    <div class="bubble bot">
      Hi! I am ACL Digital&apos;s IntelliRAG — your AI knowledge assistant for the <strong>{tenant}</strong> knowledge base. Ask me anything about your documents.
    </div>
  </div>
</div>

<div class="input-area">
  <div class="input-row">
    <textarea id="input" rows="1" placeholder="Ask a question about your documents..." onkeydown="handleKey(event)" oninput="autoResize(this)"></textarea>
    <button class="send" id="send-btn" onclick="sendMessage()" disabled>
      <svg width="15" height="15" fill="none" viewBox="0 0 24 24">
        <path d="M22 2L11 13M22 2L15 22l-4-9-9-4 20-7z" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
      </svg>
    </button>
  </div>
  <div class="powered">All data stays on-premise &middot; Powered by ACL IntelliRAG</div>
</div>

<script>
var API = window.location.origin;
var TENANT = '{tenant}';
var busy = false;

document.getElementById('input').addEventListener('input', function() {{
  document.getElementById('send-btn').disabled = !this.value.trim();
}});

function handleKey(e) {{
  if (e.key === 'Enter' && !e.shiftKey) {{ e.preventDefault(); sendMessage(); }}
}}
function autoResize(el) {{
  el.style.height = 'auto';
  el.style.height = Math.min(el.scrollHeight, 100) + 'px';
}}
function scrollBottom() {{
  var m = document.getElementById('messages');
  m.scrollTop = m.scrollHeight;
}}
function appendMsg(role, html) {{
  var msgs = document.getElementById('messages');
  var div = document.createElement('div');
  div.className = 'msg ' + role;
  div.innerHTML = '<div class="avatar ' + role + '">' + (role === 'user' ? 'U' : 'IR') + '</div><div class="bubble ' + role + '">' + html + '</div>';
  msgs.appendChild(div);
  scrollBottom();
  return div.querySelector('.bubble');
}}
function showTyping() {{
  var msgs = document.getElementById('messages');
  var div = document.createElement('div');
  div.className = 'msg bot'; div.id = 'typing-row';
  div.innerHTML = '<div class="avatar bot">IR</div><div class="typing"><span></span><span></span><span></span></div>';
  msgs.appendChild(div); scrollBottom();
}}
function removeTyping() {{ var t = document.getElementById('typing-row'); if(t) t.remove(); }}

async function sendMessage() {{
  if (busy) return;
  var input = document.getElementById('input');
  var q = input.value.trim();
  if (!q) return;
  input.value = ''; input.style.height = 'auto';
  document.getElementById('send-btn').disabled = true;
  appendMsg('user', escHtml(q));
  busy = true; showTyping();
  try {{
    var res = await fetch(API + '/api/query/', {{
      method: 'POST',
      headers: {{'Content-Type': 'application/json'}},
      body: JSON.stringify({{ tenant: TENANT, question: q }})
    }});
    var data = await res.json();
    removeTyping();
    var sourcesHtml = '';
    if (data.sources && data.sources.length) {{
      sourcesHtml = '<div class="sources">' +
        data.sources.slice(0,3).map(function(s) {{
          return '<span class="src-chip">' + escHtml(s.filename) + '</span>';
        }}).join('') + '</div>';
    }}
    var confPct = Math.round((data.confidence || 0) * 100);
    var confHtml = '<div class="conf"><div class="conf-track"><div class="conf-fill" style="width:' + confPct + '%"></div></div><span>' + confPct + '% confidence</span></div>';
    appendMsg('bot', escHtml(data.answer) + sourcesHtml + confHtml);
  }} catch(err) {{
    removeTyping();
    appendMsg('bot', 'Sorry, something went wrong. Please try again.');
  }}
  busy = false;
  document.getElementById('send-btn').disabled = true;
  document.getElementById('input').focus();
}}

function escHtml(t) {{
  return String(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/\n/g,'<br>');
}}
</script>
</body>
</html>"""
    return Response(content=html, media_type="text/html")
